@SpringBootTest
@AutoConfigureMockMvc
@ActiveProfiles("test")
@Transactional
class AuthAndPrivacyTest {

    @Autowired MockMvc mvc;
    @Autowired ObjectMapper json;

    private String register(String username) throws Exception {
        String body = """
                {"username":"%s","password":"secret123"}
                """.formatted(username);
        String res = mvc.perform(post("/api/v1/auth/register")
                        .contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return json.readTree(res).path("token").asText();
    }

    @Test
    void meRequiresToken() throws Exception {
        mvc.perform(get("/api/v1/me"))
                .andExpect(status().isUnauthorized())
                .andExpect(jsonPath("$.code").value("UNAUTHORIZED"));
    }

    @Test
    void usersCannotSeeEachOther() throws Exception {
        String alice = register("alice" + System.nanoTime());
        String bob = register("bob" + System.nanoTime());

        mvc.perform(put("/api/v1/me/notes/redis")
                        .header("Authorization", "Bearer " + alice)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"content\":\"alice 的笔记\"}"))
                .andExpect(status().isOk());

        mvc.perform(get("/api/v1/me/notes/redis")
                        .header("Authorization", "Bearer " + bob))
                .andExpect(status().isNotFound());
    }
}

